-- 2026-10-31n: MP Background timelines for batch 12, 25 more current MPs (owner's approval, "yes", 31 Oct 2026).
-- Sets background_timeline (329 entries, copied exactly from "background-batch12.json", which is not committed) and
-- background_last_checked = 2026-10-31 for member_ids 39, 54, 55, 87, 146, 152, 165, 177, 178, 193, 206, 242, 350, 373, 394, 413, 415, 429, 467, 483, 1211, 4425, 5334, 5354, 5447,
-- each only WHERE background_timeline IS NULL. Every array passed lib/background-timeline.ts validate(). Every source link was checked by Cowork
-- before the data file was written.
-- Nothing else changes. No code change. Backup of the 25 rows, off the repo: "Claude outputs/backups/2026-10-31n-mp-biography-before.csv".
-- Guards (RAISE): exactly 25 rows change, all of them these 25; the 221 existing timelines are unchanged (md5);
-- MPs with a timeline go from 221 to 246; each array equals the file exactly; 3463 entries in all afterwards.
-- Undo: 2026-10-31n-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (39, 54, 55, 87, 146, 152, 165, 177, 178, 193, 206, 242, 350, 373, 394, 413, 415, 429, 467, 483, 1211, 4425, 5334, 5354, 5447)) <> 25 THEN RAISE EXCEPTION 'expected 25 biography rows'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (39, 54, 55, 87, 146, 152, 165, 177, 178, 193, 206, 242, 350, 373, 394, 413, 415, 429, 467, 483, 1211, 4425, 5334, 5354, 5447) AND background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'a new MP already has a timeline'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 221 THEN RAISE EXCEPTION 'expected 221 MPs with a timeline before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, md5(coalesce(background_timeline::text, '')) AS th, (background_timeline IS NOT NULL) AS had
  FROM public.mp_biography b;

CREATE TEMP TABLE bt_new (member_id integer PRIMARY KEY, n integer NOT NULL, tl jsonb NOT NULL) ON COMMIT DROP;
