  (177, 10, $bt$[{"phase":"education","start":null,"end":null,"title":"School","organisation":"Pinner Park School","detail":"He attended Pinner Park School in Harrow.","source":{"title":"Gareth Thomas MP: About","url":"https://www.gareththomas.org.uk/about"}},{"phase":"education","start":null,"end":null,"title":"Secondary education","organisation":"Hatch End High School","detail":"He attended Hatch End High School.","source":{"title":"Gareth Thomas MP: About","url":"https://www.gareththomas.org.uk/about"}},{"phase":"education","start":null,"end":null,"title":"Further education","organisation":"Lowlands College","detail":"He attended Lowlands College after Hatch End High School.","source":{"title":"politics.co.uk: Gareth Thomas","url":"https://www.politics.co.uk/people/gareth-thomas/"}},{"phase":"education","start":null,"end":"1988","title":"BSc Economics","organisation":"Aberystwyth University","detail":"He studied economics at Aberystwyth University, graduating in 1988.","source":{"title":"politics.co.uk: Gareth Thomas","url":"https://www.politics.co.uk/people/gareth-thomas/"}},{"phase":"education","start":"1992","end":"1992","title":"Postgraduate Certificate in Education (PGCE)","organisation":"Thames Polytechnic","detail":"He qualified as a teacher with a PGCE from Thames Polytechnic in 1992.","source":{"title":"politics.co.uk: Gareth Thomas","url":"https://www.politics.co.uk/people/gareth-thomas/"}},{"phase":"education","start":"1996","end":"1996","title":"MA Imperial and Commonwealth History","organisation":"King's College London","detail":"He obtained an MA in Imperial and Commonwealth History from King's College London in 1996.","source":{"title":"politics.co.uk: Gareth Thomas","url":"https://www.politics.co.uk/people/gareth-thomas/"}},{"phase":"career","start":null,"end":null,"title":"Teacher","organisation":null,"detail":"He worked as a teacher at a school near his constituency before his election.","source":{"title":"Gareth Thomas MP: About","url":"https:/