  (178, 18, $bt$[{"phase":"education","start":null,"end":null,"title":"Secondary education","organisation":"Great Yarmouth Grammar School","detail":"He attended Great Yarmouth Grammar School in Norfolk.","source":{"title":"Birkbeck, University of London: John McDonnell MP, Fellow","url":"https://www.bbk.ac.uk/about-us/fellows/mcdonnell"}},{"phase":"education","start":null,"end":null,"title":"Boarding school","organisation":"De La Salle College, Ipswich","detail":"After a year at the local grammar school he was sent on a church grant to De La Salle College in Ipswich, a Catholic boarding school.","source":{"title":"Prospect: John McDonnell, the self-made socialist","url":"https://www.prospectmagazine.co.uk/magazine/john-mcdonnell-socialist-kevin-maguire-profile"}},{"phase":"education","start":null,"end":null,"title":"A levels (night school)","organisation":"Burnley Technical College","detail":"He passed his A levels through night school at Burnley Technical College.","source":{"title":"Birkbeck, University of London: John McDonnell MP, Fellow","url":"https://www.bbk.ac.uk/about-us/fellows/mcdonnell"}},{"phase":"education","start":null,"end":null,"title":"BSc Government and Politics","organisation":"Brunel University","detail":"He studied at Brunel University for a BSc in Government and Politics.","source":{"title":"Birkbeck, University of London: John McDonnell MP, Fellow","url":"https://www.bbk.ac.uk/about-us/fellows/mcdonnell"}},{"phase":"education","start":"1978","end":"1981","title":"MSc Politics and Sociology","organisation":"Birkbeck, University of London","detail":"He studied for an MSc in Politics and Sociology at Birkbeck between 1978 and 1981.","source":{"title":"Birkbeck, University of London: John McDonnell MP, Fellow","url":"https://www.bbk.ac.uk/about-us/fellows/mcdonnell"}},{"phase":"career","start":null,"end":null,"title":"Shop floor and other jobs","organisation":null,"detail":"He left school at 17 to work on the shop floor, including at Philips TV and Silent Night Beds.","source":{"title":"The Guardian: Honest John (26 September 2006)","url":"https://www.theguardian.com/politics/2006/sep/26/labourleadership.labour"}},{"phase":"career","start":null,"end":null,"title":"House parent, children's care home","organisation":"Children's home in Hayes","detail":"He and his then wife took jobs as house parents in a children's care home, responsible for 10 children.","source":{"title":"Prospect: John McDonnell, the self-made socialist","url":"https://www.prospectmagazine.co.uk/magazine/john-mcdonnell-socialist-kevin-maguire-profile"}},{"phase":"career","start":"1977","end":"1978","title":"Researcher and official","organisation":"National Union of Mineworkers","detail":"He was a researcher and official with the National Union of Mineworkers from 1977 to 1978.","source":{"title":"Wikipedia: John McDonnell","url":"https://en.wikipedia.org/wiki/John_McDonnell"}},{"phase":"career","start":"1978","end":"1982","title":"Researcher and official","organisation":"Trades Union Congress","detail":"He worked for the Trades Union Congress from 1978 until 1982.","source":{"title":"Wikipedia: John McDonnell","url":"https://en.wikipedia.org/wiki/John_McDonnell"}},{"phase":"career","start":"1985","end":"1987","title":"Head of the policy unit","organisation":"Camden Council","detail":"He was head of the policy unit at Camden council from 1985 to 1987.","source":{"title":"The Guardian: Honest John (26 September 2006)","url":"https://www.theguardian.com/politics/2006/sep/26/labourleadership.labour"}},{"phase":"career","start":"1987","end":"1997","title":"Chief executive","organisation":"Association of London Authorities, later Association of London Government","detail":"He was chief executive of the Association of London Authorities and later the Association of London Government from 1987 to 1997.","source":{"title":"politics.co.uk: John McDonnell","url":"https://www.politics.co.uk/people/john-mcdonnell/"}},{"phase":"politics","start":"1974","end":"1974","title":"Joined the Labour Party","organisation":"Labour Party","detail":"He joined the Labour Party in 1974.","source":{"title":"The Guardian: Honest John (26 September 2006)","url":"https://www.theguardian.com/politics/2006/sep/26/labourleadership.labour"}},{"phase":"politics","start":null,"end":null,"title":"Active member","organisation":"National Union of Public Employees","detail":"He was an active member of NUPE and worked in tenants' organisations and law centres.","source":{"title":"The Guardian: Honest John (26 September 2006)","url":"https://www.theguardian.com/politics/2006/sep/26/labourleadership.labour"}},{"phase":"politics","start":"1981","end":"1986","title":"Member of the Greater London Council for Hayes and Harlington","organisation":"Greater London Council","detail":"He represented Hayes and Harlington on the GLC from 1981 until its abolition in 1986.","source":{"title":"politics.co.uk: John McDonnell","url":"https://www.politics.co.uk/people/john-mcdonnell/"}},{"phase":"politics","start":"1982","end":"1985","title":"Chair of finance","organisation":"Greater London Council","detail":"He was the GLC's chair of finance from 1982 to 1985.","source":{"title":"politics.co.uk: John McDonnell","url":"https://www.politics.co.uk/people/john-mcdonnell/"}},{"phase":"politics","start":"1983","end":"1983","title":"Labour candidate, Hampstead and Highgate","organisation":"1983 general election","detail":"He stood for Labour in Hampstead and Highgate and came second to the Conservative candidate Geoffrey Finsberg.","source":{"title":"UK General Elections Results: 1983 General Election, Hampstead and Highgate","url":"https://api.parliament.uk/uk-general-elections/elections/21454"}},{"phase":"politics","start":"1984","end":"1985","title":"Deputy leader","organisation":"Greater London Council","detail":"He was deputy leader of the GLC to Ken Livingstone from 1984 to 1985.","source":{"title":"politics.co.uk: John McDonnell","url":"https://www.politics.co