  (429, 10, $bt$[{"phase":"education","start":null,"end":null,"title":"Secondary education","organisation":"Bankfield High School","detail":"Educated at Bankfield High School in Widnes.","source":{"title":"politics.co.uk: Derek Twigg","url":"https://www.politics.co.uk/people/derek-twigg/"}},{"phase":"education","start":null,"end":null,"title":"Further education","organisation":"Halton College of Further Education","detail":"Studied at Halton College of Further Education, now Riverside College.","source":{"title":"Derek Twigg MP: Biography","url":"https://derektwigg.org/biography/"}},{"phase":"career","start":null,"end":null,"title":"Civil servant","organisation":"Department of Employment","detail":"Joined the civil service at the age of 16 and worked for 19 years at the Department of Employment office in Runcorn.","source":{"title":"politics.co.uk: Derek Twigg","url":"https://www.politics.co.uk/people/derek-twigg/"}},{"phase":"career","start":null,"end":null,"title":"Branch Secretary","organisation":"Civil and Public Services Association","detail":"Became branch secretary of the CPSA union at the Department of Employment at the age of 18, serving at regional and national levels.","source":{"title":"Liverpool Echo: Cheshire: Halton: Labour candidate Derek Twigg","url":"https://www.liverpoolecho.co.uk/news/local-news/cheshire-halton-labour-candidate-derek-3427698"}},{"phase":"career","start":"1996","end":"1997","title":"Political consultant","organisation":null,"detail":"Worked as a political consultant before his election to Parliament.","source":{"title":"Wikipedia: Derek Twigg","url":"https://en.wikipedia.org/wiki/Derek_Twigg"}},{"phase":"politics","start":"1979","end":"1979","title":"Joined the Labour Party","organisation":"Labour Party","detail":"Joined the Labour Party in 1979.","source":{"title":"politics.co.uk: Derek Twigg","url":"https://www.politics.co.uk/people/derek-twigg/"}},{"phase":"politics","start":null,"end":"1985","title":"County councillor, Broadhe