  (4425, 7, $bt$[{"phase":"education","start":null,"end":null,"title":"State secondary education","organisation":null,"detail":"She was state educated in a village in Flintshire, North Wales.","source":{"title":"About Me, Jo Stevens","url":"https://www.jostevens.co.uk/about"}},{"phase":"education","start":null,"end":"1988","title":"Law degree","organisation":"Manchester University","detail":"She studied law at Manchester University, graduating in 1988.","source":{"title":"Jo Stevens MP, Welsh Labour","url":"https://www.welshlabour.wales/?p=599"}},{"phase":"education","start":"1989","end":"1989","title":"Solicitors' Professional Examination","organisation":"Manchester Polytechnic","detail":"She completed the Solicitors' Professional Examination at Manchester Polytechnic in 1989.","source":{"title":"Wikipedia: Jo Stevens","url":"https://en.wikipedia.org/wiki/Jo_Stevens"}},{"phase":"career","start":null,"end":null,"title":"Trainee solicitor","organisation":null,"detail":"She came to Cardiff for her first job as a trainee solicitor.","source":{"title":"General Election 2015: Meet the women set to vie for one of Wales' tightest marginals, WalesOnline","url":"https://www.walesonline.co.uk/news/wales-news/general-election-2015-meet-women-8968066"}},{"phase":"career","start":null,"end":"2015","title":"Solicitor and director","organisation":"Thompsons Solicitors","detail":"She worked for over 25 years as a solicitor and director of the firm, which represents trade union members, until her election in 2015.","source":{"title":"About Me, Jo Stevens","url":"https://www.jostevens.co.uk/about"}},{"phase":"career","start":null,"end":null,"title":"People and Organisation Director","organisation":"Thompsons Solicitors","detail":"She held the post of People and Organisation Director before becoming an MP.","source":{"title":"Wikipedia: Jo Stevens","url":"https://en.wikipedia.org/wiki/Jo_Stevens"}},{"phase":"politics","start":"2015","end":"2015","title":"Labour candidate, Cardiff Cent