  (5334, 19, $bt$[{"phase":"education","start":null,"end":"1987","title":"Biochemistry degree","organisation":"University of Kent","detail":"She graduated in biochemistry from the University of Kent in 1987.","source":{"title":"Kent Alumni elected to UK Parliament, University of Kent","url":"https://blogs.kent.ac.uk/development/2024/07/30/kent-alumni-elected-to-uk-parliament/"}},{"phase":"education","start":null,"end":null,"title":"MSc","organisation":"Open University","detail":null,"source":{"title":"Wikipedia: Allison Gardner","url":"https://en.wikipedia.org/wiki/Allison_Gardner"}},{"phase":"education","start":null,"end":null,"title":"PGCE","organisation":"University of Leeds","detail":null,"source":{"title":"Wikipedia: Allison Gardner","url":"https://en.wikipedia.org/wiki/Allison_Gardner"}},{"phase":"education","start":"2010-10","end":"2016-01","title":"PhD Molecular Biology","organisation":"University of Manchester","detail":"Her doctoral thesis was titled Characterising and Predicting Amyloid Mutations in Proteins.","source":{"title":"Allison Gardner, ORCID record 0000-0002-8483-121X","url":"https://orcid.org/0000-0002-8483-121X"}},{"phase":"career","start":null,"end":null,"title":"Science and PSHE teacher","organisation":null,"detail":"She spent over 25 years teaching science and PSHE in secondary schools.","source":{"title":"About, Allison Gardner","url":"https://allisongardner.co.uk/about"}},{"phase":"career","start":"2013","end":null,"title":"Research academic","organisation":"Keele University","detail":"She has been a research academic at Keele University since 2013.","source":{"title":"Kent Alumni elected to UK Parliament, University of Kent","url":"https://blogs.kent.ac.uk/development/2024/07/30/kent-alumni-elected-to-uk-parliament/"}},{"phase":"career","start":null,"end":null,"title":"Lecturer in Data Science and Programme Director, Data Science Degree Apprenticeship","organisation":"Keele University","detail":null,"source":{"title":"Allison Gardner, Fo