  (5354, 14, $bt$[{"phase":"education","start":null,"end":null,"title":"State school education","organisation":null,"detail":"He attended various state schools during a childhood spent moving between military units.","source":{"title":"General election 2024: Full list of Tewkesbury candidates, Gloucester News Centre","url":"https://gloucesternewscentre.co.uk/general-election-2024-full-list-of-tewkesbury-candidates/"}},{"phase":"education","start":null,"end":null,"title":"Initial Officer Training","organisation":"RAF College Cranwell","detail":"He trained on initial officer training course 60 at RAF College Cranwell.","source":{"title":"Hansard, House of Commons, 18 July 2024, Foreign Affairs and Defence (maiden speech)","url":"https://hansard.parliament.uk/Commons/2024-07-18/debates/CDBB0162-2412-4B51-B97D-8C95139BB2D5/ForeignAffairsAndDefence"}},{"phase":"career","start":null,"end":"2023-12","title":"Royal Air Force service","organisation":"Royal Air Force","detail":"He joined the RAF at 17 and resigned his commission in December 2023.","source":{"title":"General election 2024: Full list of Tewkesbury candidates, Gloucester News Centre","url":"https://gloucesternewscentre.co.uk/general-election-2024-full-list-of-tewkesbury-candidates/"}},{"phase":"career","start":null,"end":null,"title":"Aviator and non commissioned officer","organisation":"Royal Air Force","detail":"His operational service included Eastern Europe, the Falkland Islands and three tours of Iraq.","source":{"title":"RAF veteran and Tewkesbury's Liberal Democrat MP hopeful 'is best chance of unseating' Tories, Gloucestershire Live","url":"https://www.gloucestershirelive.co.uk/news/cheltenham-news/raf-veteran-tewkesburys-liberal-democrat-9038784"}},{"phase":"career","start":null,"end":null,"title":"Drill instructor","organisation":"Royal Air Force","detail":"He trained 1,000 recruits over three years.","source":{"title":"Wikipedia: Cameron Thomas (politician)","url":"https://en.wikipedia.org/wiki/Cameron_Thomas_(politician)"}},{"phase":"career","start":null,"end":null,"title":"RAF Police Officer","organisation":"Royal Air Force","detail":"He later served as a commissioned RAF Police Officer.","source":{"title":"RAF veteran and Tewkesbury's Liberal Democrat MP hopeful 'is best chance of unseating' Tories, Gloucestershire Live","url":"https://www.gloucestershirelive.co.uk/news/cheltenham-news/raf-veteran-tewkesburys-liberal-democrat-9038784"}},{"phase":"career","start":"2016","end":null,"title":"Posting to Imjin Barracks","organisation":"Royal Air Force","detail":"He has lived in the constituency since serving at Imjin Barracks in 2016.","source":{"title":"RAF veteran and Tewkesbury's Liberal Democrat MP hopeful 'is best chance of unseating' Tories, Gloucestershire Live","url":"https://www.gloucestershirelive.co.uk/news/cheltenham-news/raf-veteran-tewkesburys-liberal-democrat-9038784"}},{"phase":"career","start":"2021-08","end":"2021-08","title":"Planning for the British withdrawal from Afghanistan","organisation":"Royal Air Force","detail":"His team helped to plan the British withdrawal from Afghanistan.","source":{"title":"Wikipedia: Cameron Thomas (politician)","url":"https://en.wikipedia.org/wiki/Cameron_Thomas_(politician)"}},{"phase":"career","start":"2021","end":null,"title":"Deployment to East Midlands NHS","organisation":"Royal Air Force","detail":"He planned and delivered the rollout of COVID-19 vaccines across Leicestershire and Rutland.","source":{"title":"Wikipedia: Cameron Thomas (politician)","url":"https://en.wikipedia.org/wiki/Cameron_Thomas_(politician)"}},{"phase":"career","start":"2022-01","end":null,"title":"Director","organisation":"We Are Ents Ltd","detail":"He was appointed a director on 16 January 2022; the company is now dissolved.","source":{"title":"Aaron Cameron THOMAS appointments, Companies House","url":"https://find-and-update.company-information.service.gov.uk/officers/i7RJOgsczRv3qZ5ukYBLOJOuN6I/appointments"}},{"phase":"career","st